<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main">
            <van-form ref="formRef" >
                <div class="formCol">
                    <div class="item">
                        <div class="label">注册账号</div>
                        <div class="item-rt">
                            <input v-model="ruleForm.account" :rules="rules.acount" :disabled="roomInfo.id"  class="fieldInput" />
                        </div>
                    </div>
                    <div class="item" v-if="!roomInfo.id">
                        <div class="label">房间名称</div>
                        <div class="item-rt">
                            <input v-model="ruleForm.nickName" :rules="rules.nickName" :disabled="roomInfo.id"  class="fieldInput" />
                        </div>
                    </div>
                    <div class="item" v-if="!roomInfo.id">
                        <div class="label">登录密码</div>
                        <div class="item-rt">
                            <input v-model="ruleForm.passwd" :rules="rules.passwd" :disabled="roomInfo.id"  class="fieldInput" />
                        </div>
                    </div>
                    <div class="item" v-if="!roomInfo.id">
                        <div class="label">IP绑定</div>
                        <div class="item-rt">
                            <input v-model="ruleForm.whiteIp" :disabled="roomInfo.id"  class="fieldInput" />
                        </div>
                    </div>
                    <div  class="item" v-if="!roomInfo.id">
                        <div class="label">游戏显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox" direction="horizontal" v-model="ruleForm.lotlist" >
                                <template v-for="(item,index) in yxlist" :key="index+1">
                                   <van-checkbox style="margin-bottom:5px;width:120px"  icon-size="16px"  :name="item.id"  shape="square" >{{item.name}}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                    <div  class="item" style="align-items:start" v-if="roomInfo.id">
                        <div class="label">游戏显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox" direction="horizontal" v-model="ruleForm.lotlist" >
                                <template v-for="(item,index) in yxlist" :key="index+1">
                                   <van-checkbox style="margin-bottom:5px;width:120px" v-if="item.show" :disabled="item.show" icon-size="16px"  :name="item.id"  shape="square" >{{item.name}}</van-checkbox>
                                   <van-checkbox style="margin-bottom:5px;width:120px" v-else  @click="yxchan(item)" icon-size="16px"  :name="item.id"  shape="square" >{{item.name}}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                    <div  class="item" v-if="roomInfo.id">
                        <div class="label">房间网址</div>
                        <div class="item-rt">
                            <van-field style="width:200px;" v-model="ruleForm.url" class="field input"
                                       size="mini"></van-field>
                            <div class="btns" style="width:50px;"  @click="backAcout">跳转</div>
                        </div>
                    </div>
                </div>
                <div class="fobtn">
                    <div class="fobmits"  @click="canSub()" v-if="bts==2&&!roomInfo.id" style="width: 90px;">取消</div>
                    <div  class="fobmits" v-if="roomInfo.id"  @click="cancelForm()" style="width: 90px;">重新申请</div>
                    <div class="fobmits" v-if="!roomInfo.id"  @click="submitForm" >确定</div>
                    <div class="fobmits" v-if="roomInfo.id"  @click="retSetForm" >解锁/重置密码</div>
                </div>
            </van-form>
        </div>
        <van-popup v-model="lottShow" :overlay="false" position="bottom" class="popTop">
            <div class="pop-line">
                <div class="pop-lines" @click="lottShow=false">
					<div class="pop-list-line"></div>
				</div>
                <div class="pop-head">
                    <div class="pop-head-t">新增/删除游戏</div>
                    <img @click="lottShow=false" class="pop-head-img" src="@/assets/images/close.webp" />
                </div>
            </div>
            <div style="padding: 10px;color:#fff">
                <div style="color: #353f60;">步骤1:每次只可添加一个游戏。</div>
                <div class="bt-list">
                        <div class="tip-bt"  @click="lottSure">保存</div>
                        <div class="tip-bt qx"  @click="lottDialog">关闭</div>
                </div>
            </div>
        </van-popup>
    </div>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import useMd5 from '@/utils/useMd5'
const userStore = useUserStore(); 
const md5 = useMd5();

const lottShow = ref(false)
const logInfo = ref({})
const roomInfo = ref("")
const yxlist = ref([])
const lotId = ref("")
const loading = ref(false)
const lottDisable = ref(false)
const num = ref(3)
const tits = ref('申请房间')
const formRef = ref('')
const bts = ref(1)

const ruleForm = ref({
  account: '',
  nickName: '',
  passwd: '',
  whiteIp: '',
  lotlist: [],
  lotteryList: [],
  password: '',
  url: ''
})

const rules = {
  account: [
    { required: true, message: '请填写登录密码', trigger: 'blur' },
    {
      type: 'string',
      pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
      message: '密码由6位以上英文、数字组成',
      trigger: 'blur'
    }
  ],
  passwd: [
    { required: true, message: '请填写登录密码', trigger: 'blur' },
    {
      type: 'string',
      pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
      message: '密码由6位以上英文、数字组成',
      trigger: 'blur'
    }
  ]
}
onMounted(() => {
    let ust = JSON.parse(localStorage.getItem('userInfo'))
    logInfo.value = ust
    if(logInfo.value){
       getUserInfo()
    }
})
 // 方法
const backAcout = () => {
  window.open(ruleForm.value.url, '_blank')
}
const yxchan = (val) => {
  lottShow.value = true
  lotId.value = val.lotteryId
}
const lottSure = async() => {
  if (loading.value) {
    return false
  }
  loading.value = true
  setTimeout(() => {
    loading.value = false
  }, 3000)
  
  if (ruleForm.value.lotlist.length === 0) {
    let t = []
    logInfo.value.lotteryList.map(iten => {
      t.push(iten.lotteryId)
    })
    ruleForm.value.lotlist = t
    lottShow.value = false
    showToast({
        title: '至少要选择一个游戏!',
        icon: 'fail',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    return false
  }
  
  if (!lottDisable.value) {
    try {
        let res = await userStore.addRoomLottery(param.value);
        lottShow.value = false
        lottDisable.value = false
        loading.value = false
        showToast({
            title: res.data,
            icon: 'success',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        if (res.code == 200) {
            getUserInfo()
        }
    } catch (error) {
        lottShow.value = false
        lottDisable.value = false
    }
  }
  lottDisable.value = true
  setTimeout(() => {
    lottDisable.value = false
  }, 5000)
}
const retSetForm = async() => {
    await showConfirmDialog({
        title: '该房间密码重置为:123456。',
        messageAlign: 'center',  // 设置 message 居中
        width: '85vw',  
    })
    let res = await userStore.changeRoomPw();
    showToast({
        title: res.data,
        icon: 'success',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    getUserList()
}
const lottDialog = () => {
  lottShow.value = false
  let t = []
  roomInfo.value.flags.map(iten => {
    t.push(iten.lotteryId)
  })
  ruleForm.value.lotlist = t
  lottDisable.value = false
}
const getUserInfo = async() =>{
    yxlist.value = [];
    ruleForm.value.lotlist = [];
    try {
        const res = await userStore.getLotList();
        res.data.map(its=>{
            its.show = false;
        })
        yxlist.value = res.data;
        getRoomInfo()
    } catch (error) {
        console.log('获取用户信息失败')
    }
}
const canSub = () =>{
    bts.value = 1;
    getRoomInfo();
}
const  getRoomInfo = async() =>{
    try {
        const res = await userStore.getRoomInfo();
        roomInfo.value = res.data;
        ruleForm.value.account = roomInfo.value.account;
        ruleForm.value.nickName = roomInfo.value.nickName;
        ruleForm.value.url = roomInfo.value.url;
        roomInfo.value.flags.map(its=>{
            ruleForm.value.lotlist.push(its.lotteryId)
        });
        yxlist.value.map(item=>{
            roomInfo.value.flags.map(its=>{
                if(its.lotteryId == item.id){
                    item.show = true;
                }
            }); 
        })
    } catch (error) {
        console.log('获取用户信息失败')
    }
}
const submitForm = async() =>{
    if(loading.value){
        return false;
    }
    loading.value = true;
    setTimeout(()=>{
      loading.value = false;  
    },3000);
    try {
        await addMember()
    } catch (error) {
        console.log('表单验证失败')
    } 
}
const addMember = async() =>{
    loading.value = true;
    ruleForm.value.lotteryList = [];
    yxlist.value.map(item => {
        ruleForm.value.lotlist.map(items=>{
            if(item.id==items){
                item.accountId =  logInfo.value.id;
                item.lotteryId = item.id;
                item.lotteryName = item.name;
                ruleForm.value.lotteryList.push(item);            
            }
        })
    });
    let paw = ruleForm.value.passwd.toLowerCase();
    let pass = md5(paw);
    ruleForm.value.password = pass;
    setTimeout(()=>{
        loading.value = false;
    },3000)
    try {
        const res = await userStore.addRoomInfo(ruleForm.value);
        bts.value = 1;
        loading.value = false;
        showToast({ type: 'success', message: '操作成功' })
        getUserInfo()
    } catch (error) {
        console.log('表单验证失败')
    } 
}
const cancelForm = async() =>{
    await showConfirmDialog({
        title: '重新申请房间会删除旧房间数据,无法恢复,请谨慎操作',
        messageAlign: 'center',  // 设置 message 居中
        width: '85vw',  
    })
    bts.value = 2;
    ruleForm.value =  {
        account: '',
        nickName: '',
        passwd: '',
        whiteIp: '',
        lotlist:[],
    }
    roomInfo.value.id = '';
}
</script>
<style scoped>
.page{
    height:100vh;
    background-color: var(--blue-surface-b-50);
}
.btns{
    min-width: 50px;
    height: 30px;
    line-height: 30px;
    padding: 0 12px;
    border-radius: 5px;
    background-color: var(--blue-normal-hover);
    font-size: 12px;
    font-weight: 500;
    color: var(--white-white);
    text-align: center;
    cursor: pointer;
    margin-left:5px;
}
</style>
